new_8s = set([(2, 9), (3, 8), (4, 7), (4, 11), (5, 5), (5, 6), (5, 10), (6, 5), (6, 7), (6, 9), (6, 13), (7, 7), (7, 8), (7, 12), (8, 7), (8, 9), (8, 11), (9, 9), (9, 10), (10, 9), (10, 11), (11, 11)])

def check_neighbors_direct(r, c, grid):
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    count = 0
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 4:
            count += 1
    return count

# Check 4-neighbor counts for zeros that became 8s vs zeros that didn't
def check_neighbors_direct_for_0(r, c, grid):
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    count = 0
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 4:
            count += 1
    return count

zeros_data = []
for r in range(15):
    for c in range(27):
        if input_grid[r][c] == 0:
            n4 = check_neighbors_direct_for_0(r, c, input_grid)
            zeros_data.append((n4, (r, c)))

print("Zeros grouped by number of 4-neighbors:")
from collections import defaultdict
by_count = defaultdict(list)
for count, pos in zeros_data:
    by_count[count].append(pos)

for count in sorted(by_count.keys()):
    positions = by_count[count]
    became_8 = [p for p in positions if p in new_8s]
    stayed_0 = [p for p in positions if p not in new_8s]
    print(f"  {count} neighbors: 22 total zeros, {len(became_8)} became 8, {len(stayed_0)} stayed 0")
    if became_8:
        print(f"    Became 8: {sorted(became_8)}")

input_8s = [(5, 26), (6, 25), (7, 24), (8, 22), (8, 23), (9, 22), (9, 24), (10, 24)]
new_set = set([(2, 9), (3, 8), (4, 7), (4, 11), (5, 5), (5, 6), (5, 10), (6, 5), (6, 7), (6, 9), (6, 13), (7, 7), (7, 8), (7, 12), (8, 7), (8, 9), (8, 11), (9, 9), (9, 10), (10, 9), (10, 11), (11, 11)])

directions = [(1, -1), (-1, -1)]  # Down-left and up-left

# For each input 8, generate ALL diagonal cells (in both directions) and test membership
print("Checking diagonal paths:")
all_source_hits = {}
for sr, sc in input_8s:
    hits = []
    for dr, dc in directions:
        for step in range(1, 50):  # Max 50 steps
            r, c = sr + dr * step, sc + dc * step
            if 0 <= r < 15 and 0 <= c < 27:
                if (r, c) in new_set:
                    hits.append((r, c, sr, sc, dr, dc, step))
    if hits:
        all_source_hits[(sr, sc)] = hits
        print(f"\n({sr},{sc}): {len(hits)} hits")
        for h in sorted(hits):
            print(f"  {(h[0],h[1])} from ({h[2]},{h[3]}) dir=({h[4]},{h[5]}) step={h[6]}")

# Now check if all new_8s are covered
all_covered = set(h[0] for h in all_source_hits.values() if h)
print(f"\n\nTotal covered: {len(all_covered)}/22")
print(f"Missing: {sorted(new_set - all_covered)}")

